#### LCR 079. 子集
本题和 [78. 子集](https://leetcode.cn/problems/subsets/description/?envType=problem-list-v2&envId=LTRv2Gcc) 一致，稍微复杂一点的参考 [[#90 . 子集 II|90 . 子集 II]]
(https://leetcode.cn/problems/TVdhkn/)
```cpp
struct VectorHash {
	size_t operator()(const vector<int>& other) const {
		size_t seed = 0;
		for(int i = 0; i < other.size(); i++) {
			seed ^= (std::hash<int>{}(other[i]) << i);
		}
		return seed;
	}
};
class Solution {
	using Records = unordered_set<vector<int>, VectorHash>;

  private:
	void traceBack(Records& records, vector<int>& nums, vector<int> currentRecord, int currentIndex) {

		for(int i = currentIndex; i < nums.size(); i++) {
			currentRecord.push_back(nums[i]);
			records.insert(currentRecord);
			traceBack(records, nums, currentRecord, i + 1);
			currentRecord.pop_back();
		}
	}

  public:
	vector<vector<int>> subsets(vector<int>& nums) {
		Records records;
		records.insert({});
		traceBack(records, nums, {}, 0);
		vector<vector<int>> result(records.begin(), records.end());
		return result;
	}
};
```
unordered_set 其实是多余的，因为从递归树上来看，每一个节点都一定是唯一的，这样还会有计算哈希的开销
```cpp
class Solution {
    vector<int> path;
    vector<vector<int>> result = {{}};
    void traceBack(int startIndex, vector<int>& nums) {
        for (int i = startIndex; i < nums.size(); i++) {
            path.push_back(nums[i]);
            result.push_back(path);
            traceBack(i + 1, nums);
            path.pop_back();
        }
    }
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        traceBack(0, nums);
        return result;
    }
};
```
虽然不是到了根节点才记录而是每一个节点都记录情况，但总体套路大致相同，而且类似 [[#Random#砝码的重量组合|Random > 砝码的重量组合]]组合重量问题

